// Execute actual controller code using a minimal DOM adapter. Not browser acceptance.
import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFileSync} from 'node:fs';import * as model from '../web/model.js';
const source=readFileSync(new URL('../web/app.js',import.meta.url),'utf8');
const controller=source.slice(source.indexOf('let addGeneration='),source.indexOf('async function api('));
function harness(){
 const elements=new Map(),calls=[],timers=[],rows=[{id:'a',path:'visible/<img>',item:'unversioned',props:'none'},{id:'b',path:'hidden/b',item:'unversioned',props:'none'}];
 const state={mode:'live',addsEnabled:true,busy:false,failed:false,rows,selected:new Set(['a','b']),workspaceId:'w',selectionVersion:1,snapshotToken:'s'};
 function $(id){if(!elements.has(id))elements.set(id,{disabled:false,open:false,textContent:'',innerHTML:'',classList:{add(){},remove(){},toggle(){}}});return elements.get(id);}
 const scope=()=>({workspaceId:state.workspaceId,selectionVersion:state.selectionVersion,snapshotToken:state.snapshotToken});
 const context=vm.createContext({...model,Date,state,$,esc:model.safeText,modalView:'',selectionKey:()=>JSON.stringify([...state.selected]),shelfScope:scope,setTimeout:fn=>timers.push(fn),modal:(t,c)=>{$('modal').open=true;$('modal-content').innerHTML=c;context.modalView='generic';vm.runInContext('invalidateAdd()',context);},notify:m=>calls.push(['notify',m]),log:m=>calls.push(['log',m]),invalidateReads(){},renderPreview(){},render(){},setBusy:b=>state.busy=b,failSnapshot:m=>{state.failed=true;state.rows=[];state.snapshotToken=null;vm.runInContext('invalidateAdd()',context);calls.push(['failed',m]);},applySnapshot:p=>{Object.assign(state,p);vm.runInContext('invalidateAdd()',context);},api:async(path,body)=>{calls.push([path,body]);return await response(path,body);}});
 let response=async(path,b)=>path.endsWith('preflight')?{...b,mode:'live',localOnly:true,autoProps:false,expiresIn:120,planToken:'p',files:rows.map(({id,path})=>({id,path}))}:{...scope(),mode:'live',addsEnabled:true,statusRefreshed:true,snapshotToken:'s2',rows:rows.map(r=>({...r,item:'added'})),addResult:{action:'add',files:rows.map(r=>r.path),outcome:'verified',verified:true,autoProps:false,warnings:[]}};
 vm.runInContext(controller,context);return {state,$,calls,timers,context,run:s=>vm.runInContext(s,context),respond:fn=>response=fn};
}
test('open has no requests; hidden files and hostile markup escaped; separate one-use confirm',async()=>{
 const h=harness();h.run('openAdd()');assert.equal(h.calls.length,0);assert.match(h.$('modal-content').innerHTML,/hidden\/b/);assert.match(h.$('modal-content').innerHTML,/&lt;img&gt;/);await h.run('preflightAdd()');assert.deepEqual([...h.calls[0][1].ids],['a','b']);assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,0);await h.run('applyAdd()');await h.run('applyAdd()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,1);assert.match(h.$('add-last-result').textContent,/已核实添加 2/);assert(h.state.rows.every(r=>r.item==='added'));
});
test('disabled capability, demo and unsafe selection cannot call preflight',async()=>{for(const edit of [h=>h.state.mode='demo',h=>h.state.addsEnabled=false,h=>h.state.selected=new Set(['unknown']),h=>h.state.rows[0].kind='dir']){const h=harness();edit(h);h.run('openAdd()');await h.run('preflightAdd()');assert(!h.calls.some(c=>c[0].startsWith('/api/')));}});
test('selection, snapshot, expiry and dismissal invalidate confirmation',async()=>{for(const change of [h=>h.state.selected=new Set(['a']),h=>h.state.snapshotToken='new',h=>h.timers[0](),h=>{h.$('modal').open=false;h.run('invalidateAdd()');}]){const h=harness();h.run('openAdd()');await h.run('preflightAdd()');change(h);await h.run('applyAdd()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,0);}});
test('late preflight after dismissal never reenables confirmation',async()=>{const h=harness();let resolve;h.respond(()=>new Promise(r=>resolve=r));h.run('openAdd()');const pending=h.run('preflightAdd()');h.$('modal').open=false;h.run('invalidateAdd()');resolve({});await pending;assert.equal(h.$('add-confirm').disabled,true);});
test('failed or malformed result clears status and never retries',async()=>{for(const result of ['network','malformed']){const h=harness();h.run('openAdd()');await h.run('preflightAdd()');h.respond(()=>{if(result==='network')throw Error('network');return {mode:'demo'};});await h.run('applyAdd()');assert.equal(h.state.rows.length,0);assert.match(h.$('add-last-result').textContent,/结果未知/);await h.run('applyAdd()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,1);}});
test('4xx rejection not claimed as an executed write',async()=>{const h=harness();h.run('openAdd()');await h.run('preflightAdd()');h.respond(()=>{throw Object.assign(Error('rejected'),{httpStatus:409});});await h.run('applyAdd()');assert.match(h.$('add-last-result').textContent,/执行前被拒绝/);});
test('double confirm dispatches once; completion survives dismissal and failed refresh',async()=>{const h=harness();h.run('openAdd()');await h.run('preflightAdd()');let resolve;h.respond(()=>new Promise(r=>resolve=r));const pending=h.run('applyAdd()');await h.run('applyAdd()');assert.equal(h.calls.filter(c=>c[0].includes('apply')).length,1);h.$('modal').open=false;h.run('invalidateAdd()');resolve({mode:'live',workspaceId:'w',selectionVersion:1,statusRefreshed:false,snapshotToken:null,rows:[],addResult:{action:'add',files:['visible/<img>','hidden/b'],outcome:'verified',verified:true,autoProps:false,warnings:['status-refresh-failed']}});await pending;assert.match(h.$('add-last-result').textContent,/已核实添加 2/);assert.equal(h.state.rows.length,0);assert.equal(h.$('modal').open,false);});
test('scope lifecycle paths invalidate add confirmation',()=>{for(const pattern of [/function resetWorkspaceScope\(\).*invalidateAdd\(\)/,/async function refresh\(initial=false\)\{\s*if\(state.busy\)return;invalidateLock\(\);invalidateAdd\(\)/,/if\(changelistSelection!==selectionKey\(\)\).*invalidateAdd\(\)/,/addEventListener\('cancel'.*invalidateAdd\(\)/,/addEventListener\('close'.*invalidateAdd\(\)/,/function modal\(title,content\).*invalidateAdd\(\)/])assert.match(source,pattern);});
